CREATE TABLE community_event_settings (
  id INTEGER PRIMARY KEY CHECK (id = 1),
  content_json TEXT NOT NULL CHECK (json_valid(content_json)),
  revision INTEGER NOT NULL DEFAULT 1 CHECK (revision >= 1),
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

INSERT INTO community_event_settings (id, content_json) VALUES (1, '{"en":{"kicker":"Community Calendar","title":"Community Events","description":"Stay connected with upcoming socials, workshops, performances, and community dance gatherings. Check the calendar for the latest events and ways to dance with us. Next event: Uptown Lounge, October 11, 2026. Class at 6:30 PM.","nextTitle":"Next Event","nextDescription":"Join us at Uptown Lounge on October 11, 2026 for a Latin dance party with Salsa, Bachata, Merengue, Cumbia, and more! Featuring DJ Eya. Class at 6:30 PM, social dancing from 7:30 PM to 10:00 PM.","outreachTitle":"Bring a Dance to Your Community","outreachDescription":"Want us to bring a beginner-friendly dance class, demonstration, or social to your group? Contact us.","buttonLabel":"Community Calendar"},"calendarUrl":"https://calendar.google.com/calendar/embed?src=a800af1f4fa443f749fb67bff186caa877b91ad9ecfea7cfcfb779497eafae9c%40group.calendar.google.com&ctz=America%2FLos_Angeles","es":{"kicker":"Calendario comunitario","title":"Eventos comunitarios","description":"Mantente conectado con los próximos sociales, talleres, presentaciones y encuentros comunitarios de baile. Revisa el calendario para conocer los eventos más recientes y las formas de bailar con nosotros. Próximo evento: Uptown Lounge, 11 de octubre de 2026. Clase a las 6:30 PM.","nextTitle":"Próximo evento","nextDescription":"Únete a nosotros en Uptown Lounge el 11 de octubre de 2026 para una fiesta de baile latino con Salsa, Bachata, Merengue, Cumbia y más. Con DJ Eya. Clase a las 6:30 PM y baile social de 7:30 PM a 10:00 PM.","outreachTitle":"Lleva el baile a tu comunidad","outreachDescription":"¿Quieres que llevemos una clase de baile para principiantes, una demostración o un social a tu grupo? Contáctanos.","buttonLabel":"Calendario Comunitario"}}');
